#include <vector>
#include <CGAL/enum.h>

struct Point_2 {
    double x, y;
    Point_2() : x(0), y(0) {}
    Point_2(double x, double y) : x(x), y(y) {}
};

CGAL::Bounded_side point_in_polygon(const std::vector<Point_2>& polygon, const Point_2& point) {
    if (polygon.empty()) return CGAL::ON_UNBOUNDED_SIDE;

    bool inside = false;
    const int n = polygon.size();

    for (int i = 0, j = n - 1; i < n; j = i++) {
        const Point_2& p1 = polygon[i];
        const Point_2& p2 = polygon[j];

        // Check if point is on boundary
        double min_x = std::min(p1.x, p2.x);
        double max_x = std::max(p1.x, p2.x);
        double min_y = std::min(p1.y, p2.y);
        double max_y = std::max(p1.y, p2.y);

        // Check if point lies on the edge
        double dx = p2.x - p1.x;
        double dy = p2.y - p1.y;
        double cross = (point.x - p1.x) * dy - (point.y - p1.y) * dx;

        if (std::abs(cross) < 1e-10) {
            if ((point.x >= min_x - 1e-10 && point.x <= max_x + 1e-10) &&
                (point.y >= min_y - 1e-10 && point.y <= max_y + 1e-10)) {
                return CGAL::ON_BOUNDARY;
            }
        }

        // Ray casting algorithm
        if (((p1.y > point.y) != (p2.y > point.y)) &&
            (point.x < (p2.x - p1.x) * (point.y - p1.y) / (p2.y - p1.y) + p1.x)) {
            inside = !inside;
        }
    }

    return inside ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;
}

int main() {
    std::vector<Point_2> polygon = {{0,0}, {1,0}, {1,1}, {0,1}};
    Point_2 point(0.5, 0.5);
    CGAL::Bounded_side result = point_in_polygon(polygon, point);
    return 0;
}

